DO $$ DECLARE table_name text; seq text; BEGIN FOREACH table_name IN ARRAY ARRAY['employee_emergency_contacts','employee_dependents','employee_bank_accounts','employee_education','employee_work_history','employee_skills','employee_languages','employee_certifications','employee_documents','employee_training'] LOOP seq := pg_get_serial_sequence('public.' || table_name,'id'); IF seq IS NOT NULL THEN EXECUTE format('GRANT USAGE ON SEQUENCE %s TO authenticated',seq); END IF; END LOOP; END $$;
INSERT INTO storage.buckets (id,name,public,file_size_limit,allowed_mime_types) VALUES ('employee-files','employee-files',false,5242880,ARRAY['image/jpeg','image/png','image/webp','application/pdf']);
CREATE POLICY employee_files_read_own ON storage.objects FOR SELECT TO authenticated USING (bucket_id='employee-files' AND (storage.foldername(name))[1]=(select auth.uid())::text);
